pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 _val, uint256 _newVal) internal {
        try c.Initialized() {} catch { return; }
        uint256 before_;
        try c.MinSum() returns (uint256 __r) { before_ = __r; } catch { return; }
        bool reverted;
        try c.SetMinSum(_newVal) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted && c.MinSum() == before_);
    }

    function testFuzz_run(uint256 _val, uint256 _newVal) public {
        _run(_val, _newVal);
    }

    receive() external payable {}
}
